export const claimGroups=[
 ['Insured details',[['name_of_insured','Name of Insured'],['claim_contact_email','Contact Email','email'],['claim_phone_number','Phone Number','tel'],['claim_policy_number','Policy Number']]],
 ['Incident details',[['hospital_clinic_location_of_incident','Hospital / Clinic / Location of Incident'],['cause_of_incident','Cause of Incident'],['injury_details','Injury Details'],['date_of_incident_loss','Date of Incident/Loss','date'],['claim_speciality','Speciality']]],
 ['Patient and claimant',[['patient_name',"Patient’s Name"],['nationality_of_patient','Nationality of Patient'],['gender_of_patient','Gender of Patient','gender'],['claimant_solicitors_lawyers','Claimant Solicitors / Lawyers'],['claimant_name',"Claimant’s Name"],['claimant_relationship_to_patient',"Claimant’s Relationship to Patient"]]],
 ['First Notification Details',[['first_notification_received_by','First Notification Received By','notification'],['first_notification_received_on','First Notification Received On','date'],['description_of_fact_injuries','Description of Facts/Injuries','textarea']]]
];
export function mobileNumber(value){const n=String(value).replace(/[\s()-]/g,'').replace(/^\+?60/,'').replace(/^0/,'');return /^1\d{8,9}$/.test(n)?'+60'+n:null;}
export function validateClaim(data,today=new Date().toISOString().slice(0,10)){const errors={};for(const [,fields] of claimGroups)for(const [id,,type] of fields){const v=String(data[id]||'').trim();if(!v)errors[id]='This field is mandatory';else if(type==='date'&&(!/^\d{4}-\d{2}-\d{2}$/.test(v)||!Number.isFinite(Date.parse(v))||v>today))errors[id]='Enter a valid date on or before today.';}if(data.claim_contact_email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.claim_contact_email))errors.claim_contact_email='Enter a valid email address.';if(data.claim_phone_number&&!mobileNumber(data.claim_phone_number))errors.claim_phone_number='Enter a valid Malaysian mobile number.';return errors;}
export function validateAttachments(files){return files.some(f=>!/\.(pdf|doc|docx|jpeg|png|jpg|bmp|xls|xlsx)$/i.test(f.name)||f.size>6*1024*1024)?'Use PDF, Word, Excel or image files, up to 6 MB each.':'';}
export function safeServiceLink(value){if(typeof value!=='string'||!value.trim())return null;try{const u=new URL(value,'https://my-individualindemnity.doctorshield.com');return u.protocol==='https:'&&['my-individualindemnity.doctorshield.com','outlook.office365.com'].includes(u.hostname)?u.href:null;}catch{return null;}}
export class ServiceSession{
 constructor(api,now=()=>Date.now()){this.api=api;this.now=now;this.challenge=null;this.pending=false;this.policies=[];}
 async request(purpose,mobile,channel){if(this.pending)return;const phone=mobileNumber(mobile);if(!phone)throw Error('Enter a valid Malaysian mobile number.');this.pending=true;this.challenge=null;this.policies=[];try{const r=await this.api.requestServiceOtp({purpose,phone,channel});if(!r?.challengeId||!Number.isFinite(r.expiresAt)||r.expiresAt<=this.now())throw Error('Verification is unavailable. Please try again.');this.challenge={...r,purpose,phone,channel};return this.challenge;}finally{this.pending=false;}}
 async verify(code){if(this.pending)return;if(!this.challenge||this.challenge.expiresAt<=this.now())throw Error('This OTP has expired. Request a new OTP.');if(!/^\d{4,8}$/.test(code))throw Error('Please enter the valid otp');this.pending=true;try{const r=await this.api.verifyServiceOtp({challengeId:this.challenge.challengeId,code});if(!r?.verified||!Array.isArray(r.policies))throw Error('The OTP you have entered is wrong, Please check.');this.policies=r.policies;return r;}finally{this.pending=false;}}
}
